    ["Pending Battle"] = "Ожидается битва",
    ["Daily: 19:00-21:00 \n Extra: Sat, Sun 14:00-16:00"] = "Ежедневно: 19:00–21:00\nДополнительно: сб, вс 14:00–16:00",
